// The repro contract for fix-tv-unblock-2 (B): a source carrying MORE THAN
// ONE embedded audio stream (no sidecars) must publish the RENDITION layout —
// one audio track per rendition in the composed master's EXT-X-MEDIA group.
// A single-variant build muxes every audio stream into the one variant, and
// Chromium's MSE enforces one track per type on it (the live CHUNK_DEMUXER
// "Audio stream codec aac/opus doesn't match SourceBuffer codecs" fatal).
// The lane's old layout rule keyed on resolvable VOICEOVER SIDECARS only —
// blind to embedded audio — so this test arrived RED with the single-variant
// outcome; the total-audio layout rule (fix-tv-unblock-2 1.1) turns it green
// and this file pins the rule's decision shapes.

// makeTwoAudioFixture generates one tiny MKV with an h264 video track and TWO
// AAC audio tracks — the dual-audio muxed shape (both audio streams embedded
// in the source, no sidecars). Mirrors makeH264Fixture's keyframing so the
// pack segments the way real media does. Returns the absolute path. No
// network, in-process.
func makeTwoAudioFixture(t *testing.T, dir string, dur time.Duration) string {
	t.Helper()
	requireFFmpeg(t)
	out := filepath.Join(dir, "two-audio.mkv")
	secs := strconv.FormatFloat(dur.Seconds(), 'f', 2, 64)
	args := []string{
		"-nostdin", "-y",
		"-f", "lavfi", "-i", "testsrc2=size=128x72:rate=10:duration=" + secs,
		"-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100:duration=" + secs,
		"-f", "lavfi", "-i", "sine=frequency=880:sample_rate=44100:duration=" + secs,
		"-map", "0:v", "-map", "1:a", "-map", "2:a",
		"-c:v", "libx264", "-pix_fmt", "yuv420p", "-force_key_frames", "expr:gte(t,n_forced*2)", "-c:a", "aac",
		out,
	}
	if b, err := exec.Command("ffmpeg", args...).CombinedOutput(); err != nil {
		t.Fatalf("two-audio fixture generation failed: %v: %s", err, truncate(b, 400))
	}
	return out
}

// TestPackMultiAudioRenditionLayout is the spec floor for the multi-audio
// layout rule (fix-tv-unblock-2 B): packing a two-embedded-audio source
// publishes the rendition composition — one video variant, both audio streams
// as EXT-X-MEDIA renditions of the "aud" group (embedded stream 0 first,
// stream 1 second), stream copy everywhere — never the single-variant
// degenerate that MSE's one-track-per-type rule rejects.
func TestPackMultiAudioRenditionLayout(t *testing.T) {
	ctx := context.Background()
	dir := t.TempDir()
	fixture := makeTwoAudioFixture(t, dir, 12*time.Second) // head 5s + tail 7s: both phases run
	s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

	build, err := s.Pack(ctx, "it_2a", fixture, map[string]any{"format": map[string]any{"duration": "12.0"}}, nil)
	if err != nil {
		t.Fatalf("Pack: %v", err)
	}
	if build.Codecs == nil {
		t.Fatal("Pack recorded no codecs (degraded record); want the recorded codec facts")
	}
	buildDir := filepath.Join(s.Root, "it_2a", build.Nonce)

	// The composed master is the RENDITION composition: one EXT-X-STREAM-INF
	// video variant with CODECS and the AUDIO group, both embedded audio
	// streams declared as group members (rend1 then rend2), exactly one
	// DEFAULT=YES (RFC: exactly one default audio rendition).
	master := readFile(t, filepath.Join(buildDir, "index.m3u8"))
	if got := mediaURIs(master); len(got) != 2 || got[0] != "rend1/index.m3u8" || got[1] != "rend2/index.m3u8" {
		t.Fatalf("master EXT-X-MEDIA URIs = %v, want [rend1/index.m3u8 rend2/index.m3u8] (both embedded audio tracks, one per rendition):\n%s", got, master)
	}
	variants := 0
	for _, l := range strings.Split(master, "\n") {
		if strings.HasPrefix(l, "#EXT-X-STREAM-INF:") {
			variants++
		}
	}
	if variants != 1 {
		t.Fatalf("master carries %d EXT-X-STREAM-INF variants, want exactly the one video rendition (both audio streams as renditions):\n%s", variants, master)
	}
	if !strings.Contains(master, `AUDIO="aud"`) || !strings.Contains(master, `CODECS="avc1.`) {
		t.Fatalf("master variant line missing the audio group / video CODECS:\n%s", master)
	}
	if n := strings.Count(master, "DEFAULT=YES"); n != 1 {
		t.Fatalf("master carries %d DEFAULT=YES, want exactly one:\n%s", n, master)
	}

	// The variant split is honest: rend0 is the video alone; rend1/rend2 are
	// the two embedded audio streams, copied (aac), audio-only.
	video := streamKinds(probeStreams(t, filepath.Join(buildDir, "rend0", "init_0.mp4")))
	if video["video"] != 1 || video["audio"] != 0 {
		t.Fatalf("rend0 init streams = %v, want video only (the audio moved to renditions)", video)
	}
	audioCodec := func(init string) string {
		for _, st := range probeStreams(t, init) {
			if st["codec_type"] == "audio" {
				c, _ := st["codec_name"].(string)
				return c
			}
		}
		return ""
	}
	if got := audioCodec(filepath.Join(buildDir, "rend1", "init_1.mp4")); got != "aac" {
		t.Fatalf("rendition 1 codec = %q, want the copied aac (no re-encode)", got)
	}
	if got := audioCodec(filepath.Join(buildDir, "rend2", "init_2.mp4")); got != "aac" {
		t.Fatalf("rendition 2 codec = %q, want the copied aac (no re-encode)", got)
	}

	// The published build passes the lane's own validator.
	if err := s.ValidateBuild("it_2a", build.Nonce); err != nil {
		t.Fatalf("ValidateBuild(multi-audio rendition) = %v, want nil", err)
	}
}

// TestVariantLayoutKeysOnTotalAudio pins the layout decision table
// (fix-tv-unblock-2 D2): rendition iff embedded+sidecars > 1 — one variant
// per audio stream, embedded first — and total <= 1 stays the single-variant
// degenerate exactly as before. The embedded=0 rows are the probe-failure
// fail-open shape (embeddedAudioCount degrades to 0, the decision riding the
// sidecar column alone); the 1+2 row is 1.2's byte-identical-flag pin anchor.
func TestVariantLayoutKeysOnTotalAudio(t *testing.T) {
	rels := func(vs []variantPlaylist) []string {
		out := make([]string, len(vs))
		for i, v := range vs {
			out[i] = v.rel
		}
		return out
	}
	cases := []struct {
		name               string
		embedded, sidecars int
		want               []string
	}{
		{"no_audio_stays_single_variant", 0, 0, []string{"rend0"}},
		{"one_embedded_stays_single_variant", 1, 0, []string{"rend0"}},
		{"one_sidecar_stays_single_variant", 0, 1, []string{"rend0"}},
		{"two_embedded_is_rendition", 2, 0, []string{"rend0", "rend1", "rend2"}},
		{"embedded_plus_sidecar_is_rendition", 1, 1, []string{"rend0", "rend1", "rend2"}},
		{"fail_open_sidecars_only_is_rendition", 0, 2, []string{"rend0", "rend1", "rend2"}},
		{"one_embedded_two_sidecars_is_rendition", 1, 2, []string{"rend0", "rend1", "rend2", "rend3"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := rels(variantLayout(tc.embedded, tc.sidecars)); !slices.Equal(got, tc.want) {
				t.Fatalf("variantLayout(%d, %d) = %v, want %v", tc.embedded, tc.sidecars, got, tc.want)
			}
		})
	}
}

// TestEmbeddedAudioProbeFailsOpen pins the build-time source probe
// (fix-tv-unblock-2 D1): the count reads the ORIGINAL file's real audio
// streams, and a failed probe fails open to 0 — the layout decision degrades
// to the sidecar discriminator and the pack never fails on the probe.
func TestEmbeddedAudioProbeFailsOpen(t *testing.T) {
	ctx := context.Background()
	dir := t.TempDir()
	s := newTestService(t, filepath.Join(dir, "streams"), 5*time.Second)

	if got := s.embeddedAudioCount(ctx, filepath.Join(dir, "missing.mkv")); got != 0 {
		t.Fatalf("embeddedAudioCount(missing file) = %d, want the fail-open 0", got)
	}
	if got := s.embeddedAudioCount(ctx, dir); got != 0 {
		t.Fatalf("embeddedAudioCount(directory) = %d, want the fail-open 0", got)
	}
	fixture := makeTwoAudioFixture(t, dir, 2*time.Second)
	if got := s.embeddedAudioCount(ctx, fixture); got != 2 {
		t.Fatalf("embeddedAudioCount(two-audio fixture) = %d, want 2 (the file's real audio streams)", got)
	}
}
